solution.Solution.cs:
public static class Solution
{
    public static double ToCelsius(double fahrenheit)
    {
        return (fahrenheit - 32) * 5 / 9;
    }

    public static double Average(int a, int b, int c)
    {
        return (a + b + c) / 3.0;
    }

    public static int ParseOrDefault(string text, int fallback)
    {
        return int.TryParse(text, out int value) ? value : fallback;
    }

    public static decimal TotalPrice(decimal unitPrice, int quantity, decimal taxRate)
    {
        decimal net = unitPrice * quantity;
        return Math.Round(net * (1 + taxRate), 2, MidpointRounding.AwayFromZero);
    }
}

unitTests:
Test("Fahrenheit to Celsius", () =>
{
    CheckNear(ToCelsius(212), 100);
    CheckNear(ToCelsius(32), 0);
    CheckNear(ToCelsius(-40), -40);
    CheckNear(ToCelsius(98.6), 37);
});

Test("an exact average", () =>
{
    CheckNear(Average(1, 2, 2), 5.0 / 3);
    CheckNear(Average(10, 20, 30), 20);
    CheckNear(Average(-1, 0, 0), -1.0 / 3);
});

Test("parsing safely", () =>
{
    CheckEq(ParseOrDefault("42", 0), 42);
    CheckEq(ParseOrDefault("-7", 0), -7);
    CheckEq(ParseOrDefault("4x", 5), 5);
    CheckEq(ParseOrDefault("", 9), 9);
    CheckEq(ParseOrDefault("3.5", 1), 1);
});

Test("money with decimal", () =>
{
    CheckEq(TotalPrice(19.99m, 3, 0.2m), 71.96m);
    CheckEq(TotalPrice(0.125m, 1, 0m), 0.13m);
    CheckEq(TotalPrice(2.50m, 4, 0.08m), 10.80m);
});

